mapper.select:
SELECT a.id, a.actor_user_id AS userId, COALESCE(u.username, CASE WHEN a.actor_user_id = '' THEN a.target_id END) AS username, COALESCE(u.display_name, '') AS displayName, a.action, a.ip_address AS ipAddress, a.user_agent AS userAgent, a.detail, a.created_at AS createdAt FROM `bf_audit_log` a LEFT JOIN `bf_user` u ON a.actor_user_id = u.id WHERE a.action IN ('LOGIN_SUCCESS', 'LOGIN_FAILED', 'LOGOUT', 'FORCE_LOGOUT', 'PASSWORD_CHANGED', 'ACCOUNT_LOCKED', 'ACCOUNT_UNLOCKED')
AND (u.username LIKE CONCAT('%', #{username}, '%') OR (a.actor_user_id = '' AND a.target_id LIKE CONCAT('%', #{username}, '%')))
AND a.action = #{status}
AND a.created_at >= #{startDate}
AND a.created_at <= #{endDate}
ORDER BY a.created_at DESC
